const GITHUB_USERNAME = "composiohq";

const main = async () => {
  const trialId = (await readFile("/logs/trial_id", "utf8")).trim();
  const slackChannel = `agent-results-${trialId}`;

  const composio = new Composio({
    apiKey: process.env.COMPOSIO_API_KEY,
    provider: new VercelProvider(),
  });

  const session = await composio.createSession(USER_ID);
  const tools = await session.getTools({
    apps: ["github", "slack"],
  });

  const prompt = `You are an automation agent.\n\nSteps:\n1. Use the GITHUB_GET_A_USER tool to fetch the GitHub profile for ${GITHUB_USERNAME}.\n2. Extract the bio and public_repos fields from the response.\n3. Use the SLACK_POST_MESSAGE tool to send a message to the Slack channel ${slackChannel} with the text: \"User ${GITHUB_USERNAME} has {public_repos} repos. Bio: {bio}\".\n\nOnly call the tools required to complete the task.`;

  await generateText({
    model: openai("gpt-4o-mini"),
    tools,
    prompt,
  });
};

